-- Starter content for the business "Ideas" tab (RU/UZ/EN). DRAFT: approved by ZAYA.
-- Idempotent by sequence number; texts are refreshed on re-apply.
insert into public.content_items (id, kind, title, body, sort)
select md5('zaya-idea-' || n)::uuid, kind,
       jsonb_build_object('ru', ru_t, 'uz', uz_t, 'en', en_t),
       jsonb_build_object('ru', ru_b, 'uz', uz_b, 'en', en_b),
       n
from (values
  (1, 'pr', 'Покажите людей, а не только продукт', 'Odamlarni ko‘rsating, faqat mahsulotni emas', 'Show people, not just the product', 'Бренды, которые снимают реальных людей разного возраста, роста и типажа, вызывают больше доверия. Покажите в кампании тех, кто действительно пользуется вашим продуктом.', 'Turli yosh, bo‘y va tipajdagi haqiqiy odamlarni suratga oladigan brendlarga ishonch yuqori bo‘ladi. Kampaniyada mahsulotingizdan haqiqatan foydalanadiganlarni ko‘rsating.', 'Brands that shoot real people of different ages, heights and looks earn more trust. Feature those who actually use your product.'),
  (2, 'pr', 'Расскажите историю за кадром', 'Kadr ortidagi hikoyani aytib bering', 'Tell the behind-the-scenes story', 'Короткий репортаж со съёмки (подготовка, команда, выбор образов) даёт охваты без бюджета на рекламу. Опубликуйте его в Stories и Reels.', 'Suratga olishdan qisqa reportaj (tayyorgarlik, jamoa, obraz tanlash) reklama byudjetisiz qamrov beradi. Uni Stories va Reels’ga joylang.', 'A short report from the shoot (preparation, team, choosing looks) brings reach without an ad budget. Post it in Stories and Reels.'),
  (3, 'pr', 'Запустите коллаборацию с локальным автором', 'Mahalliy muallif bilan hamkorlik boshlang', 'Start a collaboration with a local creator', 'Сотрудничество с известным в городе фотографом или блогером расширяет аудиторию и добавляет кампании живости.', 'Shahardagi taniqli fotograf yoki bloger bilan hamkorlik auditoriyani kengaytiradi va kampaniyaga jonlilik qo‘shadi.', 'Working with a well-known local photographer or blogger widens your audience and brings life to the campaign.'),
  (4, 'pr', 'Сделайте закрытый показ для клиентов', 'Mijozlar uchun yopiq namoyish o‘tkazing', 'Hold a closed show for clients', 'Небольшое событие для постоянных клиентов и партнёров создаёт ощущение причастности и приносит контент для соцсетей.', 'Doimiy mijozlar va hamkorlar uchun kichik tadbir ishtirok hissini beradi va ijtimoiy tarmoqlar uchun kontent olib keladi.', 'A small event for regular clients and partners creates a sense of belonging and brings content for social media.'),
  (5, 'pr', 'Соберите пресс-кит после съёмки', 'Suratga olishdan keyin press-kit yig‘ing', 'Put together a press kit after the shoot', 'Отберите 10 лучших кадров, короткое описание кампании и контакты. С таким набором легче получить публикации в СМИ.', '10 ta eng yaxshi kadr, kampaniyaning qisqa tavsifi va kontaktlarni tanlang. Bunday to‘plam bilan ommaviy axborot vositalarida chiqish osonroq.', 'Pick the 10 best shots, a short campaign description and contacts. With such a kit it is easier to get media coverage.'),
  (6, 'pr', 'Опубликуйте итоги кампании', 'Kampaniya natijalarini e’lon qiling', 'Publish the campaign results', 'Через неделю после запуска покажите результаты: охваты, отзывы, лучшие кадры. Это закрепляет эффект и мотивирует аудиторию вернуться.', 'Ishga tushirilgandan bir hafta o‘tib natijalarni ko‘rsating: qamrov, sharhlar, eng yaxshi kadrlar. Bu ta’sirni mustahkamlaydi.', 'A week after launch show the results: reach, feedback, best shots. It reinforces the effect and brings the audience back.'),
  (7, 'media', 'Снимайте вертикально и коротко', 'Vertikal va qisqa suratga oling', 'Shoot vertical and short', 'Для Reels, TikTok и Stories лучше работают ролики 15–30 секунд в вертикальном формате с кадром лица в первые две секунды.', 'Reels, TikTok va Stories uchun 15–30 soniyali vertikal roliklar yaxshi ishlaydi, yuz birinchi ikki soniyada ko‘rinishi kerak.', 'For Reels, TikTok and Stories, 15–30 second vertical videos work best, with the face in frame in the first two seconds.'),
  (8, 'media', 'Один образ — несколько форматов', 'Bitta obraz — bir nechta format', 'One look, several formats', 'На одной съёмке получите фото, вертикальное видео и короткий ролик. Это экономит бюджет и обеспечивает единый стиль везде.', 'Bitta suratga olishdan foto, vertikal video va qisqa rolik oling. Bu byudjetni tejaydi va hamma joyda yagona uslubni ta’minlaydi.', 'Get photos, vertical video and a short clip from one shoot. It saves budget and keeps a single style everywhere.'),
  (9, 'media', 'Используйте естественный свет', 'Tabiiy yorug‘likdan foydalaning', 'Use natural light', 'Дневной свет у окна или на улице делает кадры живыми и убедительными. Студийная съёмка нужна только для строгого каталога.', 'Deraza yonidagi yoki ko‘chadagi kunduzgi yorug‘lik kadrlarni jonli va ishonchli qiladi. Studiya faqat qat’iy katalog uchun kerak.', 'Daylight by a window or outdoors makes frames lively and believable. A studio is only needed for a strict catalogue.'),
  (10, 'media', 'Подберите площадки под аудиторию', 'Auditoriyaga mos maydonlarni tanlang', 'Pick platforms for your audience', 'Instagram и TikTok — широкая аудитория и молодёжь, Telegram-каналы — лояльные клиенты, Facebook и YouTube — старшая аудитория и длинные форматы.', 'Instagram va TikTok — keng auditoriya va yoshlar, Telegram-kanallar — sodiq mijozlar, Facebook va YouTube — keksa auditoriya va uzun formatlar.', 'Instagram and TikTok reach a wide, young audience, Telegram channels reach loyal clients, Facebook and YouTube reach an older audience and long formats.'),
  (11, 'media', 'Дайте чёткое техническое задание', 'Aniq texnik topshiriq bering', 'Give a clear brief', 'Список кадров, референсы и сроки в брифе сокращают число правок и ускоряют результат. Чем точнее бриф, тем меньше вопросов к команде.', 'Brifdagi kadrlar ro‘yxati, namunalar va muddatlar tuzatishlar sonini kamaytiradi va natijani tezlashtiradi. Brif qanchalik aniq bo‘lsa, jamoaga shuncha kam savol tug‘iladi.', 'A shot list, references and deadlines in the brief cut the number of revisions and speed up the result. The more precise the brief, the fewer questions for the team.'),
  (12, 'motivation', 'Говорим стереотипам нет', 'Stereotiplarga yo‘q deymiz', 'We say no to stereotypes', 'Красота не имеет единого стандарта. Рост, возраст, телосложение и внешность — это разнообразие, которое делает бренд живым.', 'Go‘zallikning yagona standarti yo‘q. Bo‘y, yosh, qomat va tashqi ko‘rinish — brendni jonli qiladigan xilma-xillikdir.', 'Beauty has no single standard. Height, age, build and looks are the diversity that makes a brand alive.'),
  (13, 'motivation', 'Работаем без границ', 'Chegarasiz ishlaymiz', 'We work without borders', 'Мы отбираем людей за характер и мастерство, а не за шаблонную картинку. Ваш бренд может показать больше, чем принято.', 'Biz odamlarni qolipdagi suratga emas, xarakter va mahoratiga qarab tanlaymiz. Brendingiz odatdagidan ko‘proq narsani ko‘rsata oladi.', 'We choose people for character and skill, not for a template image. Your brand can show more than is usual.'),
  (14, 'motivation', 'Уникальность — это сила', 'Noyoblik — bu kuch', 'Uniqueness is strength', 'Люди доверяют тем, кто выглядит как они сами. Показывайте разные лица, и ваша аудитория увидит себя в вашем бренде.', 'Odamlar o‘zlariga o‘xshaganlarga ishonadi. Turli yuzlarni ko‘rsating, shunda auditoriyangiz brendingizda o‘zini ko‘radi.', 'People trust those who look like themselves. Show different faces and your audience will see themselves in your brand.'),
  (15, 'motivation', 'Смело — значит заметно', 'Jasorat — e’tiborga tushish demak', 'Bold means noticeable', 'Кампании, которые ломают привычные рамки, запоминаются надолго. Не бойтесь выбрать неожиданного героя вашей истории.', 'Odatiy doiralarni buzadigan kampaniyalar uzoq eslab qoladi. Hikoyangizning kutilmagan qahramonini tanlashdan qo‘rqmang.', 'Campaigns that break the usual frames are remembered for a long time. Do not be afraid to choose an unexpected hero for your story.'),
  (16, 'motivation', 'Профессионализм важнее шаблона', 'Mutaxassislik qolipdan muhimroq', 'Professionalism over template', 'Хорошая модель умеет передать настроение и смысл, а не только красивую форму. Доверьтесь опыту и характеру.', 'Yaxshi model faqat chiroyli shaklni emas, kayfiyat va ma’noni yetkaza oladi. Tajriba va xarakterga ishoning.', 'A good model conveys mood and meaning, not just a beautiful form. Trust experience and character.'),
  (17, 'motivation', 'Ваша высота начинается здесь', 'Sizning cho‘qqingiz shu yerdan boshlanadi', 'Your heights begin here', 'Каждый сильный бренд когда-то сделал первый смелый шаг. Сделайте его вместе с ZAYA.', 'Har bir kuchli brend bir paytlar birinchi jasur qadamni qo‘ygan. Uni ZAYA bilan birga qo‘ying.', 'Every strong brand once took a first bold step. Take it together with ZAYA.')
) as t(n, kind, ru_t, uz_t, en_t, ru_b, uz_b, en_b)
on conflict (id) do update set title = excluded.title, body = excluded.body;
